from pathlib import Path
import ast,pprint

def edit(name,fn):
 p=Path(name);s=p.read_bytes().decode('utf-8').replace('\r\n','\n');s=fn(s);ast.parse(s);p.write_bytes(s.replace('\n','\r\n').encode('utf-8'))
edit('gui/window.py',lambda s:s.replace('_vid_btn("🔇  SOUND OFF")','_vid_btn(tr("🔇  SOUND OFF"))').replace('_vid_btn("✕  CLOSE")','_vid_btn(tr("✕  CLOSE"))').replace('        _W = 250\n','        _W = 310\n'))
edit('gui/providers_panel.py',lambda s:s.replace('star = "   ★ recommended" if','star = tr("   ★ recommended") if').replace('return f"{mark}  Code with {entry[\'label\']}{star}"','return tr("{mark}  Code with {name}{star}", mark=mark, name=entry["label"], star=star)').replace('text = self._coding_combo.itemText(i)','text = self._coding_combo.message_at(i)').replace('f"{len(items)} model{\'s\' if len(items) != 1 else \'\'} "\n                       f"found on this server — pick one above."','tr("{count} model(s) found on this server — pick one above.", count=len(items))').replace('f"✓  {len(items)} available: "\n                           f"{\', \'.join(str(v) for v, _ in items[:8])}"','tr("✓  {count} available: {items}", count=len(items), items=", ".join(str(v) for v, _ in items[:8]))').replace('words = " and ".join(f"{m.lower()}" for m in missing)','words = join_messages(tr(" and "), [tr(m) for m in missing])').replace('tr, render, QLabel','tr, render, join_messages, QLabel'))
p=Path('gui/i18n.py');s=p.read_text(encoding='utf-8');tree=ast.parse(s);n=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='PT_BR' for t in n.targets));d=ast.literal_eval(n.value)
d.update({'   ★ recommended':'   ★ recomendado','{mark}  Code with {name}{star}':'{mark}  Programar com {name}{star}','{count} model(s) found on this server — pick one above.':'{count} modelo(s) encontrados neste servidor — escolha acima.'})
lines=s.splitlines(keepends=True);a=sum(map(len,lines[:n.lineno-1]));b=sum(map(len,lines[:n.end_lineno]));s=s[:a]+'PT_BR = '+pprint.pformat(d,sort_dicts=True,width=100)+'\n'+s[b:];p.write_text(s,encoding='utf-8',newline='\n')
p=Path('readme.md');raw=p.read_bytes();s=raw.decode('utf-8');newline='\r\n' if b'\r\n' in raw else '\n';s=s.replace('\r\n','\n')
heading='## Interface language / Idioma da interface\n\n'
text='Open **Setup → Customise Assistant → Interface language** to choose **English** or **Português (Brasil)**, then select **Apply changes**. The desktop interface updates immediately and remembers the choice after restart. English is the default when no valid preference is saved. Cancel leaves the language unchanged.\n\nEm **Configuração → Personalizar assistente → Idioma da interface**, escolha **English** ou **Português (Brasil)** e clique em **Aplicar alterações**. A troca é imediata e fica salva para a próxima inicialização. O idioma da interface é independente do idioma da conversa e da voz. Conteúdo do usuário, respostas geradas, nomes de provedores/modelos e textos fornecidos por plugins/serviços permanecem como recebidos; diálogos nativos seguem o sistema.\n\n'
s += '\n'+heading+text;p.write_bytes(s.replace('\n',newline).encode('utf-8'))
print('Documentation and final text coverage updated')